"""V1 current-income-only candidate, real completed public-node regressions.

The inline fixture contains all223 unique legal-hu first-difference views plus
40 short cleared discard views from completed V5/F development data. It is
compressed only to avoid duplicating long ordered public histories in source.
The decoded payload is SHA256-pinned and retains each original line/prefix.
No original GameState, opponent hand, wall order, or seed is given to policy.
The legacy/current action deltas were fixed from the already audited arithmetic,
not selected by any full-game outcome. Tests query no game or new seed.
"""
import base64
import copy
from contextlib import redirect_stdout, redirect_stderr
import hashlib
import io
import json
from pathlib import Path
from types import FunctionType
import unittest
from unittest.mock import patch
import zlib

import advanced_policy
import worker
import v1_income_policy

_PAYLOAD_SHA256 = '327405956cdd639c1b95940d85e35ca7b47974b6e950d560f89f85ee74f95274'
_PAYLOAD_COMPRESSED = ''
_RAW = zlib.decompress(base64.b64decode(_PAYLOAD_COMPRESSED))
assert hashlib.sha256(_RAW).hexdigest() == _PAYLOAD_SHA256
FIXTURE = json.loads(_RAW)
CASES = FIXTURE['cases']


def canonical(value):
    return json.dumps(value, sort_keys=True, ensure_ascii=False, separators=(',', ':'))


def context_for(case):
    view = copy.deepcopy(case['view'])
    context = advanced_policy.build_context(view, worker.build_context(view), worker)
    return view, context


def choose(policy, case):
    view, context = context_for(case)
    with redirect_stdout(io.StringIO()), redirect_stderr(io.StringIO()):
        return worker.choose_action(case['phase'], view, context, policy, advanced=True)


class V1IncomePolicyTests(unittest.TestCase):
    def setUp(self):
        self.original = advanced_policy.load_policy()
        self.bindings = dict(vars(self.original))
        self.score_bindings = dict(vars(self.original.score))
        self.candidate = v1_income_policy.load_policy()

    def assert_original_intact(self):
        for current, before in [(vars(self.original), self.bindings), (vars(self.original.score), self.score_bindings)]:
            self.assertEqual(set(current), set(before))
            for name, value in before.items():
                self.assertIs(current[name], value, name)

    def test_real_kong_shot_uses_current_income_denominator_and_changes_pung_to_legal_hu(self):
        case = next(case for case in CASES if case['id'] == 'e597e5944d796dc52d801937a35ad0a96d49138d6475556b26dee33158166c65')
        view, context = context_for(case)
        self.assertEqual(view['decision']['choices'], ['pass', 'hu', 'pung'])
        self.assertEqual(v1_income_policy._known_discard_reward_ratio(context.player, context.dealer, view['decision']['from']), .5)
        self.assertEqual(choose(self.original, case), {'type': 'respond', 'choice': 'pung'})
        self.assertEqual(choose(self.candidate, case), {'type': 'respond', 'choice': 'hu'})
        self.assertEqual(choose(self.original, case), case['originalAction'])
        self.assert_original_intact()

    def test_real_rob_kong_uses_two_current_points_instead_of_plain_base_one(self):
        case = next(case for case in CASES if case['id'] == '11c64c3ac12d147987b147d642a5f7a4e89f96858d1ba6a22a978a82dd11a935')
        view, context = context_for(case)
        self.assertEqual(view['decision']['choices'], ['pass', 'hu'])
        self.assertEqual(v1_income_policy._known_rob_points(context.player, worker.to_external(view['decision']['tile'])), 2)
        self.assertEqual(choose(self.original, case), {'type': 'respond', 'choice': 'pass'})
        self.assertEqual(choose(self.candidate, case), {'type': 'respond', 'choice': 'hu'})
        self.assert_original_intact()

    def test_all263_public_frames_A_candidate_A_are_deterministic_legal_and_isolated(self):
        self.assertEqual(len(CASES), 263)
        self.assertEqual(sum(case['phase'] == 'respond' for case in CASES), 223)
        counts = {'known-kong-shot': 0, 'known-rob-kong': 0, 'delegate': 0}
        changed_by_target = dict.fromkeys(counts, 0)
        changed = 0
        for case in CASES:
            with self.subTest(id=case['id'], origin=case['origin']):
                view = case['view']
                self.assertEqual(hashlib.sha256(canonical({'phase': case['phase'], 'view': view}).encode()).hexdigest(), case['id'])
                self.assertNotIn('seed', view)
                for other in view['opponents']:
                    self.assertNotIn('hand', other)
                for event in view['publicActions']:
                    if event['kind'] == 'draw': self.assertEqual(set(event), {'seat', 'kind'})
                before = canonical(view)
                self.assertEqual(choose(self.original, case), case['originalAction'])
                self.assertEqual(choose(self.candidate, case), case['candidateAction'])
                self.assertEqual(choose(self.original, case), case['originalAction'])
                self.assertEqual(canonical(view), before)
                changed += case['candidateAction'] != case['originalAction']
                changed_by_target[case['target']] += case['candidateAction'] != case['originalAction']
                counts[case['target']] += 1
                self.assert_original_intact()
        self.assertEqual(changed, 16)
        self.assertEqual(changed_by_target, {'known-kong-shot': 14, 'known-rob-kong': 2, 'delegate': 0})
        self.assertEqual(counts, {'known-kong-shot': 21, 'known-rob-kong': 2, 'delegate': 240})

    def test_only_two_functions_have_private_derivations_other_functions_and_score_are_original(self):
        for name, value in vars(self.original).items():
            if name not in {'check_hu', 'check_robkong'}:
                self.assertIs(getattr(self.candidate, name), value, name)
        for name in ['check_hu', 'check_robkong']:
            old, new = getattr(self.original, name), getattr(self.candidate, name)
            self.assertIsInstance(new, FunctionType)
            self.assertIsNot(new, old)
            self.assertIsNot(new.__globals__, old.__globals__)
            self.assertIs(new.__globals__['score'], old.__globals__['score'])
            self.assertEqual(new.__globals__['HU_DECLINE_THRESHOLD'], 1)
        self.assert_original_intact()

    def test_private_loaders_and_source_derivation_are_deterministic(self):
        another = v1_income_policy.load_policy()
        self.assertIsNot(another.check_hu.__globals__, self.candidate.check_hu.__globals__)
        self.assertEqual(self.candidate._v1_income_derivation, another._v1_income_derivation)
        info = self.candidate._v1_income_derivation
        self.assertEqual(info['policy'], 'ebony72-advanced-current-income-v1')
        self.assertEqual(info['sourceSha256'], FIXTURE['strategySha256'])
        self.assertEqual(set(info['functions']), {'check_hu', 'check_robkong'})
        for name, data in info['functions'].items():
            self.assertEqual(data['replacements'], 1)
            self.assertEqual(len(data['originalSourceSha256']), 64)
            self.assertEqual(len(data['derivedSourceSha256']), 64)
            self.assertIn('@@', data['diff'])
        self.assert_original_intact()

    def test_changed_source_is_rejected_even_if_manifest_validation_is_bypassed(self):
        with patch.object(v1_income_policy, '_source_bytes', return_value=b'changed source'), patch.object(advanced_policy, 'verify_vendor', return_value={}):
            with self.assertRaisesRegex(ValueError, 'source|provenance|pinned'):
                v1_income_policy.load_policy()
        self.assert_original_intact()

    def test_invalid_target_completion_fails_explicitly_without_teacher_fallback(self):
        case = next(case for case in CASES if case['target'] == 'known-kong-shot')
        with patch.object(v1_income_policy, 'evaluate_v1_income', return_value=None):
            with self.assertRaises(worker.AdapterError): choose(self.candidate, case)
        self.assert_original_intact()

    def test_non_target_ordinary_hu_and_short_discard_never_call_new_income_helper(self):
        for case in [next(case for case in CASES if case['target']=='delegate' and case['phase']=='respond'), next(case for case in CASES if case['phase']=='discard')]:
            with patch.object(v1_income_policy, 'evaluate_v1_income', side_effect=AssertionError('non-target called current-income helper')):
                self.assertEqual(choose(self.candidate, case), case['originalAction'])
        self.assert_original_intact()

    def test_missing_history_is_still_rejected_before_any_policy_decision(self):
        case = copy.deepcopy(CASES[0]);case['view'].pop('publicActions')
        for policy in [self.original, self.candidate]:
            with self.assertRaises(worker.AdapterError): choose(policy, case)
        self.assert_original_intact()


if __name__ == '__main__': unittest.main()
